   import { isServer, QueryClient } from '@tanstack/react-query';

   function makeQueryClient() {
     return new QueryClient({
       defaultOptions: { queries: { staleTime: 60_000 } },
     });
   }

   export function getQueryClient() {
     if (isServer) return makeQueryClient();          // new client on every request
     // reuse a client on the browser so it isn’t recreated on a suspend
     if (!globalThis.__browserQuery) {
       globalThis.__browserQuery = makeQueryClient();
     }
     return globalThis.__browserQuery;
   }
   ```

3. **Wrap the whole app in `ReactQueryStreamedHydration`** (inside `QueryClientProvider`).  
